{ arg out=0, freq=440, amp=0.1, gate=1, modIndex=5, modRatio=1.5;
    var sig, carrier, modulator, env;
    env = EnvGen.ar(
        Env.adsr(0.005, 0.1, 0.5, 0.5, curve: -4),
        gate: gate,
        doneAction: 2
    );
    modulator = SinOsc.ar(freq * modRatio);
    carrier = SinOsc.ar(freq + (modulator * (freq * modIndex * env)));
    sig = carrier * amp * env;
    Out.ar(out, sig ! 2);
}
